 function start(activityId,temporaryName=''){const generation=getState().dataGeneration,opened=document.querySelector('#dialog[open]'),openedHeader=opened?.firstElementChild;return timerQueue.run('start:'+activityId,async now=>{const s=getState(),current=s.running;if(!s.activities.some(a=>a.id===activityId&&isSelectable(s,a)))throw Error('请先恢复这个分类或标签');if(current?.activityId===activityId&&(!temporaryName||current.temporaryName===temporaryName)){if(opened?.open&&opened.firstElementChild===openedHeader)await closeModal({refresh:false});return;}const operation=D.uid();await save(s=>{if(s.dataGeneration!==generation)throw Error('数据空间已变化，请重新开始');let next=s;if(next.running?.activityId===activityId)next=D.switchTimer(next,null,now);next=D.switchTimer(next,activityId,now,operation);if(next.running)next.running.temporaryName=temporaryName.trim();return next;},{operationId:operation,timerOnly:true});if(opened?.open&&opened.firstElementChild===openedHeader)await closeModal({refresh:false});toast('已开始记录');});}
