  const s=getState(),group=s.activityGroups.find(g=>g.id===groupId),tools=`<div class="catalog-picker-tools">${group?button('catalog-groups','‹ 分类','','text-button'):''}${button('picker-manage','管理分类与标签',group?.id??'','text-button')}${group?button('picker-create-label','＋ 固定标签',group.id,'text-button'):''}</div>`;
